/*! IGDC Unified Payment & Monetization Engine
 * PG approval-preparation version.
 * All direct PG execution is gated by /.netlify/functions/status.
 */
(function (w, d) {
  "use strict";

  if (w.IGDC && w.IGDC.__ENGINE_READY__) return;
  w.IGDC = w.IGDC || {};
  w.IGDC.__ENGINE_READY__ = true;

  const CFG = w.IGDC.PAYCFG || {};
  const ENDPOINTS = {
    checkout: CFG.checkout || "/.netlify/functions/checkout",
    status: CFG.status || "/.netlify/functions/status"
  };

  const $ = (selector, root) => (root || d).querySelector(selector);
  const $$ = (selector, root) => Array.from((root || d).querySelectorAll(selector));
  const now = () => Date.now();
  const safe = (value) => (value === undefined || value === null ? "" : value);
  const amountOf = (value) => (Number.isFinite(Number(value)) ? Number(value) : 0);

  function fetchJSON(url, options) {
    return fetch(url, options).then(async (response) => {
      const payload = await response.json().catch(() => ({}));
      if (!response.ok) {
        const error = new Error(payload.error || `http_${response.status}`);
        error.payload = payload;
        error.status = response.status;
        throw error;
      }
      return payload;
    });
  }

  function modal(title, html) {
    let box = d.getElementById("igdc-modal");
    if (!box) {
      box = d.createElement("div");
      box.id = "igdc-modal";
      box.style.cssText = "position:fixed;inset:0;z-index:999999;background:rgba(0,0,0,.55);display:none;";
      box.innerHTML = `
        <div style="max-width:520px;margin:10vh auto;background:#fff;border-radius:14px;overflow:hidden">
          <div style="padding:12px 16px;font-weight:800;border-bottom:1px solid #eee;display:flex;justify-content:space-between">
            <span id="igdc-modal-title"></span>
            <button id="igdc-modal-close" type="button" aria-label="닫기">×</button>
          </div>
          <div id="igdc-modal-body" style="padding:16px"></div>
        </div>`;
      d.body.appendChild(box);
      $("#igdc-modal-close", box).onclick = () => { box.style.display = "none"; };
    }
    $("#igdc-modal-title", box).textContent = title || "안내";
    $("#igdc-modal-body", box).innerHTML = html || "";
    box.style.display = "block";
  }

  let STATUS_CACHE = { timestamp: 0, value: null };
  function getStatus(force) {
    if (!force && STATUS_CACHE.value && now() - STATUS_CACHE.timestamp < 120000) {
      return Promise.resolve(STATUS_CACHE.value);
    }

    return fetchJSON(ENDPOINTS.status)
      .catch(() => ({
        ok: false,
        enabled: false,
        pg: { status: "status_unavailable", executionEnabled: false },
        payment: {},
        features: {}
      }))
      .then((value) => {
        STATUS_CACHE = { timestamp: now(), value };
        return value;
      });
  }

  function pendingMessage(status, purpose) {
    const pgStatus = status?.pg?.status || "pending_pg_approval";
    const donation = purpose === "donation";
    const title = donation ? "도네이션 결제 준비 중" : "결제 준비 중";
    const text = pgStatus === "maintenance"
      ? "현재 결제 시스템은 점검 중입니다."
      : donation
        ? "현재 도네이션 결제는 PG 승인 및 연결 준비 단계입니다."
        : "현재 결제 시스템은 PG 승인 및 연결 준비 단계입니다.";

    modal(title, `<div style="font-size:14px;line-height:1.6">${text}<br/>결제 가능 상태가 되면 자동으로 활성화됩니다.</div>`);
  }

  function routePay(options) {
    const opt = options || {};
    const mode = opt.mode || "auto";
    const amount = amountOf(opt.amount);
    const url = safe(opt.url);
    const title = safe(opt.title);
    const method = String(opt.method || "card").toLowerCase();
    const source = opt.source || w.location.pathname;
    const purpose = String(opt.purpose || "commerce").toLowerCase();

    if (mode === "affiliate" || mode === "external") {
      if (url) w.location.href = url;
      return Promise.resolve();
    }

    if (mode === "tracking") {
      if (w.dataLayer) w.dataLayer.push({ event: "igdc_track", title, source });
      if (url) w.location.href = url;
      return Promise.resolve();
    }

    return getStatus().then((status) => {
      const executable = Boolean(status?.payment?.[method]) && status?.pg?.executionEnabled === true;
      if (!executable) {
        pendingMessage(status, purpose);
        return null;
      }

      const payload = {
        method,
        amount,
        title,
        source,
        purpose,
        meta: opt.meta || {}
      };

      return fetchJSON(ENDPOINTS.checkout, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(payload)
      })
        .then((result) => {
          if (result.redirectUrl) {
            w.location.href = result.redirectUrl;
            return;
          }
          if (result.html) {
            modal("결제", result.html);
            return;
          }
          if (result.mode === "donation_information") {
            modal("도네이션 안내", "도네이션 결제 연결 준비 중입니다.");
            return;
          }
          modal("결제", "결제 세션을 준비하지 못했습니다.");
        })
        .catch((error) => {
          if (error?.payload?.error === "pg_pending_approval") {
            pendingMessage(error.payload, purpose);
            return;
          }
          modal("오류", "결제 서버에 연결할 수 없습니다.");
        });
    });
  }

  function bind(element) {
    if (!element || element.__igdcBound) return;
    element.__igdcBound = true;

    element.addEventListener("click", (event) => {
      const href = element.getAttribute("href") || "";
      const opt = {
        mode: element.dataset.mode || "auto",
        method: element.dataset.method,
        amount: element.dataset.amount,
        title: element.dataset.title || element.textContent.trim(),
        url: href,
        purpose: element.dataset.purpose || "commerce"
      };

      if (opt.mode !== "external") event.preventDefault();
      routePay(opt);
    });
  }

  function scan() {
    $$("[data-pay],[data-method],[data-amount],[data-mode]").forEach(bind);
  }

  if ("MutationObserver" in w) {
    new MutationObserver(scan).observe(d.documentElement, { childList: true, subtree: true });
  }

  d.addEventListener("DOMContentLoaded", scan);
  w.IGDC.pay = routePay;
  w.IGDC.openPayment = routePay;
  d.addEventListener("psom:payment", (event) => routePay(event.detail || {}));
  w.addEventListener("message", (event) => {
    if (event?.data?.type === "IGDC_PAY") routePay(event.data.payload || {});
  });
})(window, document);
